const items = $input.all();
const results = [];
const seen = new Set();
for (const item of items) {
  if (!item.binary) continue;
  const msgId = item.json.id || item.json.threadId || Math.random().toString(36);
  const rawDate = item.json.internalDate || item.json.date || null;
  let emailDate = new Date().toISOString().slice(0, 10);
  if (rawDate) { const d = new Date(Number(rawDate) > 0 ? Number(rawDate) : rawDate); if (!isNaN(d.getTime())) emailDate = d.toISOString().slice(0, 10); }
  for (const key of Object.keys(item.binary)) {
    const bin = item.binary[key];
    const fileName = (bin.fileName || '').trim();
    if (!fileName) continue;
    const isPdf = (bin.mimeType || '').toLowerCase().includes('pdf') || fileName.toLowerCase().endsWith('.pdf');
    if (!isPdf) continue;
    const dedupKey = msgId + '::' + fileName;
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);
    results.push({ json: { msgId, emailDate, fileName, source: 'gmail-xp' }, binary: { data: bin } });
  }
}
return results;

const src = $('Filtrar PDFs XP').all();
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const meta = src[i] ? src[i].json : {};
  const pages = (j.pages || []).map(p => 'data:image/png;base64,' + ((p && p.image && p.image.data) || ''));
  out.push({ json: Object.assign({}, meta, { pages: pages, pageCount: pages.length, convertError: pages.length ? undefined : 'sem paginas' }) });
