return out;

const items = $input.all();
const results = [];
const SCHEMA_TEXT = [
  'Você é um extrator preciso de faturas de cartão de crédito do banco XP (XP Investimentos / xpi.com.br).',
  'Você recebe as PÁGINAS da fatura como imagens, em ordem. Devolva EXCLUSIVAMENTE um objeto JSON válido, sem markdown, sem comentários.',
  '',
  'Schema (chaves em inglês, valores em português quando texto):',
  '{',
  '  "schema": "xp_fatura_v1",',
  '  "card_holder": string|null,',
  '  "card_last4": string|null,',
  '  "statement_period": { "open_date": "YYYY-MM-DD"|null, "close_date": "YYYY-MM-DD"|null },',
  '  "due_date": "YYYY-MM-DD"|null,',
  '  "payment_code": string|null,',
  '  "total_balance": number|null,',
  '  "minimum_payment": number|null,',
  '  "previous_balance": number|null,',
  '  "credits_payments": number|null,',
  '  "limit": number|null,',
  '  "available_limit": number|null,',
  '  "points_balance": number|null,',
  '  "transactions": [',
  '    {',
  '      "date": "YYYY-MM-DD"|null,',
  '      "description": string,',
  '      "merchant": string|null,',
  '      "category": string,',
  '      "amount": number,',
  '      "installment_info": string|null',
  '    }',
  '  ],',
  '  "warnings": [string]',
  '}',
  '',
  'Regras:',
  '- category é UMA de: mercado, restaurante, transporte, assinaturas, saude, educacao, casa, viagem, tecnologia, lazer, vestuario, servicos_bancarios, taxas, saque, pagamento, outros.',
  '- Números com ponto decimal, sem símbolos (R$ 1.234,56 -> 1234.56).',
  '- Datas YYYY-MM-DD; se o ano não estiver explícito, use o ano do período da fatura.',
  '- NÃO invente valores; ilegível => null + warnings.',
  '- Cada linha de transação = um objeto; "Parcela X/Y" vai em installment_info.',
  '- POSITIVO compras, NEGATIVO estornos/pagamentos.',
  '- Ignore rodapés de marketing, SAC, Ouvidoria.',
  '- Se a soma das transactions ± créditos divergir do total_balance mais de 0.05, registre em warnings (não ajuste).',
  '- Responda SOMENTE o JSON.'
].join('\n');
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const pages = item.json.pages || [];
  if (!pages.length) {
    results.push({ json: Object.assign({}, item.json, { skipped: true, skipReason: 'sem páginas: ' + (item.json.convertError || '?') }), binary: item.binary, pairedItem: { item: i } });
    continue;
  }
