  const buf = Buffer.from(JSON.stringify(reqBody), 'utf8');
  const bin = await this.helpers.prepareBinaryData(buf, 'llm_body.json', 'application/json');
  results.push({ json: Object.assign({}, item.json, { skipped: false }), binary: { data: item.binary ? item.binary.data : null, reqbody: bin }, pairedItem: { item: i } });
}
return results;

const llmItems = $input.all();
const src = $('Filtrar PDFs XP').all();
const results = [];
function parseNum(s) {
  if (s === null || s === undefined) return null;
  let str = String(s).trim().replace(/[^0-9.,-]/g, '');
  if (!str) return null;
  if (str.includes(',') && str.includes('.')) str = str.replace(/\./g, '').replace(',', '.');
  else if (str.includes(',')) str = str.replace(',', '.');
  const n = parseFloat(str);
  return isNaN(n) ? null : n;
}
const CATS = ['mercado','restaurante','transporte','assinaturas','saude','educacao','casa','viagem','tecnologia','lazer','vestuario','servicos_bancarios','taxas','saque','pagamento','outros'];
let okCount = 0, errCount = 0, txCount = 0;
for (let i = 0; i < llmItems.length; i++) {
  const meta = src[i] ? src[i].json : {};
  const raw = llmItems[i].json.llmResponse || (llmItems[i].json.choices && llmItems[i].json.choices[0] && llmItems[i].json.choices[0].message ? llmItems[i].json.choices[0].message.content : '') || '';
  let data = null, parsedOk = false, error = null;
  try {
    let js = raw;
    const cb = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (cb) js = cb[1];
    const s = js.indexOf('{'); const e = js.lastIndexOf('}');
    if (s >= 0 && e > s) js = js.slice(s, e + 1);
    data = JSON.parse(js);
    parsedOk = true; okCount++;
  } catch (err) { error = err.message; errCount++; }
  if (!data) data = { schema: 'xp_fatura_v1', transactions: [], warnings: ['parse falhou: ' + error] };
  data.schema = 'xp_fatura_v1';
  const txs = Array.isArray(data.transactions) ? data.transactions : [];
  txs.forEach(t => {
    t.amount = parseNum(t.amount);
    if (!t.category || !CATS.includes(t.category)) t.category = 'outros';
    if (typeof t.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(t.date)) { /* ok */ } else { t.date = null; }
  });
  ['total_balance','minimum_payment','previous_balance','credits_payments','limit','available_limit','points_balance'].forEach(k => { data[k] = parseNum(data[k]); });
  if (data.statement_period && data.statement_period.open_date && !/^\d{4}-\d{2}-\d{2}$/.test(data.statement_period.open_date)) data.statement_period.open_date = null;
  if (data.statement_period && data.statement_period.close_date && !/^\d{4}-\d{2}-\d{2}$/.test(data.statement_period.close_date)) data.statement_period.close_date = null;
  if (data.due_date && !/^\d{4}-\d{2}-\d{2}$/.test(data.due_date)) data.due_date = null;
  // validação de soma
  const sum = txs.reduce((a, t) => a + (t.amount || 0), 0);
  const total = data.total_balance;
  if (total !== null) {
    const credits = data.credits_payments || 0;
    const diff = Math.abs((sum + credits) - total);
    if (diff > 0.05 && !Array.isArray(data.warnings)) data.warnings = [];
    if (diff > 0.05 && data.warnings.indexOf('soma divergente do total em ' + diff.toFixed(2)) === -1) data.warnings.push('soma divergente do total em ' + diff.toFixed(2));
  }
  // nome do ficheiro: período fechado + last4 + msgId curto
  const period = (data.statement_period && data.statement_period.close_date) ? data.statement_period.close_date : meta.emailDate;
  const last4 = (data.card_last4 || '0000').toString().padStart(4, '0');
  const uploadName = 'XP_' + period + '_' + last4 + '_' + String(meta.msgId || '').slice(-8) + '.json';
  txCount += txs.length;
  results.push({ json: {
    parsedOk, error, uploadName,
    emailDate: meta.emailDate, fileName: meta.fileName, msgId: meta.msgId,
    record: data,
    _summary: { file: meta.fileName, parsedOk, transactions: txs.length, total: data.total_balance, due: data.due_date, warnings: (data.warnings || []).length }
  }});
}
console.log('XP consolidate: ok=' + okCount + ' err=' + errCount + ' tx=' + txCount);
return results;

// Saída do Dedup Check (HTTP). Referência linear à cadeia é segura (não é side-branch agendada).
const checks = $input.all();
const consolidados = $('Consolidar JSON').all();
const results = [];
let skipped = 0;
for (let i = 0; i < checks.length; i++) {
  const existe = checks[i].json && checks[i].json.files && checks[i].json.files.length > 0;
  if (existe) { skipped++; continue; }
  const orig = consolidados[i];
  if (!orig) continue;
  results.push({ json: orig.json });
}
if (results.length > 0) results[0].json._summary = Object.assign({}, results[0].json._summary, { duplicados: skipped });
console.log('XP dedup: novos=' + results.length + ' duplicados=' + skipped);
return results;

const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const jsonStr = JSON.stringify(item.json.record, null, 2);
  const buf = Buffer.from(jsonStr, 'utf8');
  const binaryData = await this.helpers.prepareBinaryData(buf, item.json.uploadName, 'application/json');
  results.push({ json: { uploadName: item.json.uploadName, parsedOk: item.json.parsedOk, _summary: item.json._summary, record: item.json.record }, binary: { data: binaryData } });
}
return results;

// Depois do upload o $json é o objeto do ficheiro — stats vêm da referência linear ao Consolidar
const cons = $('Consolidar JSON').all();
const novos = $input.all().length;
const parts = [];
for (const c of cons) {
  const s = c.json._summary || {};
  const w = s.warnings ? ' ⚠' + s.warnings : '';
  parts.push('• ' + (s.file || '?') + ' → ' + (s.transactions || 0) + ' transações, total R$ ' + (s.total !== null && s.total !== undefined ? s.total.toFixed(2) : '?') + ', vence ' + (s.due || '?') + (s.parsedOk ? '' : ' [PARSE FALHOU]') + w);
}
const message = '💳 Fatura XP processada (' + novos + ' nova(s)):\n' + parts.join('\n');
return [{ json: { message, novos } }];

